INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'ks'), 'A1', 'greetings', 'Greetings', 'Greet your hosts and introduce yourself in Kashmiri.', 'You''ve just checked in to a houseboat on the Dal Lake. Bashir sahab, the owner, welcomes you.', '“Assalaam alaikum” (or “Namaskar”) is the everyday hello. Kashmiri is polite with “tuhi” (you) and requests ending in -iv: “diyiv” (please give), “kariv” (please do). Call a man “baya” (brother) and a woman “beni” (sister).', 1, 'published', datetime('now'), datetime('now'), 1);
