INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'ks'), 'A1', 'transport', 'Transport', 'Take autos and shikaras, and agree the fare first.', 'You''re at Lal Chowk and need an auto to Nishat Bagh.', 'Srinagar''s autos don''t use meters: agree the fare before you get in. Shikaras on the Dal Lake have official hourly rates set by the tourism department, but boatmen at Dal Gate often ask for more, so agree the price and the route first.', 2, 'published', datetime('now'), datetime('now'), 1);
