INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ks') AND slug = 'chhu-and-chhe'), (SELECT id FROM languages WHERE code = 'en'), '“Is”: “chhu” and “chhe”', '“Chhu” is “is” with a masculine word and “chhe” with a feminine one: “myon naav chhu Alex” (my name is Alex), “Kasheer chhe khoobsoorat” (Kashmir is beautiful). For “I am” a man says “chhus” and a woman “chhes”.');
